import React from "react";
import ModulItem from "./modulItemComponenet";

class Myinfo extends React.Component {
    constructor(props){
        super(props);
        this.state = {
            user: null
        };
    }

    componentDidMount() {
        if (!JSON.parse(localStorage.getItem("user"))) {
            window.location.href = "/login";
        }
            fetch(`http://localhost:8000/api/?page=${page}`, {
                headers: {
                    "Accept": "application/json",
                    "Authorization": "Bearer " + localStorage.getItem("token")
                }
            })
            .then(res => res.json())
            .then(json => {
                const newPosts = json.posts.data;

                this.setState({
                    posts: [...posts, ...newPosts],
                    base_URL: json.base_URL,
                    loading: false,
                    page: page + 1,
                    hasMore: json.posts.next_page_url !== null
                });
            })
            .catch(err => {
                console.log("ERR:", err);
                this.setState({ loading: false, hasMore: false });
            });
    }
    render() {
        return (
            <>
            <div className="d-flex flex-column flex-md-row align-items-center justify-content-between gap-4 mb-4">
                <div className="d-flex align-items-center gap-4">
                    <img src={this.state.user.base_URL + this.state.user.img} alt={this.state.user.name} className="rounded-circle border"
                        style={{width: "120px"}}/>
                    <div>
                        <h4 className="fw-bold mb-1">{this.state.user.name}</h4>
                        <p className="mb-2">{this.state.user.bio??'no bio'}</p>
                        <p className="mb-2">Birth Date: diriz</p>
                        <p className="mb-2">Years ago : diriz </p>

                        <div className="d-flex gap-4 flex-wrap">
                            <div><strong>34</strong> Posts</div>
                            <div>
                                <a href="#" className="text-decoration-none text-color hover-border" data-bs-toggle="modal"
                                    data-bs-target="#followersModal">
                                    <strong>66</strong> Followers
                                </a>
                            </div>
                            <div>
                                <a href="#" className="text-decoration-none text-color hover-border" data-bs-toggle="modal"
                                    data-bs-target="#followingModal">
                                    <strong>99</strong> Following
                                </a>
                            </div>
                        </div>
                    </div>
                </div>
                <div className="d-flex flex-column gap-2">
                    <a href="/profile/edit"
                        className="btn btn-theme boder active d-flex align-items-center gap-2 rounded-pill px-3">
                        <i className="bi bi-pencil"></i>
                        Edit Profile
                    </a>
                    <a href="/add/post" className="btn btn-theme boder active d-flex align-items-center gap-2 rounded-pill px-3">
                        <i className="bi bi-camera-reels"></i>
                        Upload Post
                    </a>
                </div>
            </div>

                <div className="modal fade" id="followersModal" tabindex="-1" aria-labelledby="followersModalLabel" aria-hidden="true">
                    <div className="modal-dialog modal-dialog-scrollable">
                        <div className="modal-content item-back">
                            <div className="modal-header">
                                <h5 className="modal-title" id="followersModalLabel">Followers</h5>
                                <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                            </div>
                            <div className="modal-body">
                                <ModulItem/>
                                <ModulItem/>
                                <ModulItem/>
                                <ModulItem/>
                            </div>
                        </div>
                    </div>
                </div>


                <div className="modal fade" id="followingModal" tabindex="-1" aria-labelledby="followingModalLabel" aria-hidden="true">
                    <div className="modal-dialog modal-dialog-scrollable">
                        <div className="modal-content item-back">
                            <div className="modal-header">
                                <h5 className="modal-title" id="followingModalLabel">Following</h5>
                                <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                            </div>
                            <div className="modal-body">
                                <ModulItem/>
                            </div>
                        </div>
                    </div>
                </div>
            </>
        );
    }
}
export default Myinfo;
